    def upload_file(
        file_path: str,
        display_name: Optional[str] = None,
        type: Optional[FileType] = None,
    ) -> Any:
        resolved_name = display_name or os.path.basename(file_path)
        with open(file_path, "rb") as handle:
            uploaded = _upload_file(
                client,
                handle,
                display_name=resolved_name,
                **drop_none({"type": type}),
            )
        return to_dict(uploaded)

